import sys

def main():
    data = sys.stdin.read().split()
    N = int(data[0]); M = int(data[1]); S = data[2]
    MOD = 998244353
    states = 1 << N
    distinct = sorted(set(S))
    other_w = 26 - len(distinct)

    # precompute transitions for each distinct char
    trans = []
    for c in distinct:
        t = [0]*states
        for mask in range(states):
            # build d
            d = [0]*(N+1)
            for j in range(1, N+1):
                d[j] = d[j-1] + ((mask >> (j-1)) & 1)
            new = [0]*(N+1)
            for j in range(1, N+1):
                v = new[j-1]
                if d[j] > v:
                    v = d[j]
                if S[j-1] == c and d[j-1]+1 > v:
                    v = d[j-1]+1
                new[j] = v
            nm = 0
            for j in range(1, N+1):
                if new[j] - new[j-1]:
                    nm |= 1 << (j-1)
            t[mask] = nm
        trans.append(t)

    cur = [0]*states
    cur[0] = 1
    for _ in range(M):
        nxt = [0]*states
        for mask in range(states):
            v = cur[mask]
            if v == 0:
                continue
            if other_w:
                nxt[mask] = (nxt[mask] + v*other_w) % MOD
            for t in trans:
                nm = t[mask]
                nxt[nm] = (nxt[nm] + v) % MOD
        cur = nxt

    ans = [0]*(N+1)
    for mask in range(states):
        if cur[mask]:
            ans[bin(mask).count('1')] = (ans[bin(mask).count('1')] + cur[mask]) % MOD
    print(' '.join(map(str, ans)))

main()
